package mz.bam.seeky.android;
import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import java.io.*;import java.util.*;

/** Grants a single staged APK to Android's interactive installer. Never installs silently. */
public final class ApkInstallActivity extends WorkspaceActivity {
    static final String MIME="application/vnd.android.package-archive";Uri source;File prepared;String name="Aplicação.apk";boolean busy,cancelled;
    static boolean accepts(String name,String mime){return "apk".equalsIgnoreCase(MediaFormats.ext(name==null?"":name))||MIME.equals(mime);}
    static void open(Context c,Uri uri,String name){Intent i=new Intent(c,ApkInstallActivity.class).setData(uri).putExtra("name",name).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri(name,uri));c.startActivity(i);}
    String title(){return "Instalar aplicação Android";}
    public void onCreate(Bundle state){source=getIntent().getData();String label=getIntent().getStringExtra("name");if(label!=null)name=AudioTitles.limit(label,160,300);if(state!=null){String path=state.getString("prepared","");try{File f=new File(path).getCanonicalFile();if(DiskWalker.inside(directory(this).getCanonicalFile(),f)&&f.isFile())prepared=f;}catch(Exception ignored){}}super.onCreate(state);}
    static File directory(Context c){File root=new File(c.getCacheDir(),"install-apks");root.mkdirs();return root;}
    void load(){if(content==null)return;content.removeAllViews();note(name);note("A instalação é confirmada no instalador do Android.");if(source==null){note("Ficheiro indisponível.");return;}if(busy){note("A preparar aplicação…");return;}if(prepared==null)action("Preparar APK",this::prepare);else if(!getPackageManager().canRequestPackageInstalls())action("Permitir instalação desta origem",()->{try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception e){PlusUi.error(this,e);}});else action("Abrir instalador Android",this::install);}
    void prepare(){if(busy)return;busy=true;load();final Context app=getApplicationContext();PlusUi.longRun(this,()->{File temp=new File(directory(app),UUID.randomUUID()+".part"),target=new File(directory(app),UUID.randomUUID()+".apk");boolean ok=false;try{long size=0,limit=Math.min(2147483648L,Math.max(0,directory(app).getUsableSpace()-33554432L));try(InputStream in=openSource(app,source);FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;){if(cancelled)throw new InterruptedIOException();size+=n;if(size>limit)throw new IOException("Espaço insuficiente para preparar este APK.");out.write(b,0,n);}out.getFD().sync();}if(size==0)throw new IOException("O APK está vazio.");java.nio.file.Files.move(temp.toPath(),target.toPath());prepared=target;ok=true;PlusUi.post(this,this::load);}finally{temp.delete();if(!ok)target.delete();busy=false;PlusUi.post(this,this::load);}});}
    static InputStream openSource(Context c,Uri uri)throws IOException{if(uri==null)throw new FileNotFoundException();if("file".equals(uri.getScheme())){File f=new File(uri.getPath());if(!StorageAccess.allowed(c,f))throw new FileNotFoundException("Ficheiro sem acesso autorizado.");return new FileInputStream(f);}if(!"content".equals(uri.getScheme()))throw new FileNotFoundException("Localização inválida.");InputStream in=c.getContentResolver().openInputStream(uri);if(in==null)throw new FileNotFoundException();return in;}
    static Uri share(Context c,File file){return new Uri.Builder().scheme("content").authority(c.getPackageName()+".files").appendPath("apk").appendPath(file.getName()).build();}
    Intent installer(){Uri uri=share(this,prepared);Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,MIME).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri(name,uri));return i;}
    void install(){try{if(prepared==null||!prepared.isFile())throw new IOException("Prepare novamente o APK.");if(!getPackageManager().canRequestPackageInstalls()){load();return;}startActivity(installer());}catch(Exception e){PlusUi.error(this,e);}}
    protected void onResume(){super.onResume();load();}protected void onSaveInstanceState(Bundle out){if(prepared!=null)out.putString("prepared",prepared.getPath());super.onSaveInstanceState(out);}protected void onDestroy(){cancelled=true;super.onDestroy();}
}
